VALUES (396899, 'tt5698496', NULL, 'The Girl Without Hands', 'La jeune fille sans mains', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/f4EVSG3CPshLfnUe3hdQBVyliX0.jpg', 'https://image.tmdb.org/t/p/original/tvknAnXj7x7Cm7WKpqB8QRzFLYh.jpg', 'A poor miller gets tricked by the Devil and accidentally sells his daughter for a bit of gold. But Satan can''t take her because she''s too pure and has wept on her hands. So Satan orders the miller to cut her hands off. It''s the beginning of the young girl''s journey towards freedom.', NULL, NULL, 1.7685, 6.97, 0, 1.01, '2026-11-21 03:29:05', '2026-11-21 03:29:05')
