VALUES (23438, 'tt0103262', NULL, 'Wild Hearts Can''t Be Broken', 'Wild Hearts Can''t Be Broken', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/kY7KaiN3vh4g49Pn3ShM2ATnFVw.jpg', 'https://image.tmdb.org/t/p/original/wAneBIQKVFSXpBsXP8Z85tzNyUB.jpg', 'A runaway orphan, young Sonora, persists in a menial job mucking stables in Doc Carver''s travelling stunt show. Her great wish is to become a death-defying "diving girl," but Doc refuses her pleas. Undaunted, Sonora''s gutsy resolve finally convinces him to give her a break. On the brink of stardom, however, a cruel twist of fate threatens to destroy her dream.', NULL, NULL, 1.5123, 7.306, 0, 1.06, '2026-11-21 03:29:05', '2026-11-21 03:29:05')
