VALUES (50073, 'tt0024772', NULL, 'Wild Boys of the Road', 'Wild Boys of the Road', 'movie', 1933, 'https://image.tmdb.org/t/p/w500/c1nq13h6Q7C90LTnxFIV5XaI7VQ.jpg', 'https://image.tmdb.org/t/p/original/2QNS5eIO1fVRuiUryHutWu7BEqZ.jpg', 'At the height of the Great Depression, Tommy''s mother has been out of work for months when Eddie''s father loses his job. Eager not to burden their parents, the two high school sophomores decide to hop the freight trains and look for work.', NULL, NULL, 1.1706, 6.8, 0, 1.01, '2026-11-21 03:29:05', '2026-11-21 03:29:05')
