VALUES (46315, 'tt0066516', NULL, 'Valerie and Her Week of Wonders', 'Valerie a týden divů', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/lY0IkdouazLBpPYot8dsPAsJqHK.jpg', 'https://image.tmdb.org/t/p/original/cygF3MFce4MDpvyqDQXNvZiytc4.jpg', 'Valerie, a Czechoslovakian teenager living with her grandmother, is blossoming into womanhood, but that transformation proves secondary to the effects she experiences when she puts on a pair of magic earrings. Now seeing the world around her in a different light, Valerie must endure her sexual awakening while attempting to discern reality from fantasy as she encounters lecherous priest Gracian, a vampire-like stranger and otherworldly carnival folk.', NULL, NULL, 2.6867, 7.0, 0, 6.63857142857142861e+01, '2026-07-15 12:01:52', '2026-11-21 03:29:05')
