VALUES (44896, 'tt1192628', NULL, 'Rango', 'Rango', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/A5MP1guV8pbruieG0tnpPIbaJtt.jpg', 'https://image.tmdb.org/t/p/original/mOtKQlXdL5J4lwqcSFlkZmgmFeZ.jpg', 'When Rango, a lost family pet, accidentally winds up in the gritty, gun-slinging Western town of Dirt, the theater-loving lizard suddenly finds himself the newly appointed sheriff. Welcomed as the last hope the town has been waiting for, Rango is forced to play his new role to the hilt and uncover the truth behind a looming water crisis—before his act catches up with him.', NULL, NULL, 10.3348, 6.925, 0, 21.193125, '2026-07-15 12:01:52', '2026-11-21 03:29:05')
