VALUES (11322, 'tt1152836', NULL, 'Public Enemies', 'Public Enemies', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/3KgtekisQBrHRsm2cD5UOB6Ce3k.jpg', 'https://image.tmdb.org/t/p/original/rlKB2moKVOPasy4Dr19QluzbJgA.jpg', 'Depression-era bank robber John Dillinger''s charm and audacity endear him to much of America''s downtrodden public, but he''s also a thorn in the side of J. Edgar Hoover and the fledgling FBI. Desperate to capture the elusive outlaw, Hoover makes Dillinger his first Public Enemy Number One and assigns his top agent, Melvin Purvis, the task of bringing him in dead or alive.', NULL, NULL, 4.9038, 6.7, 0, 2.28888888888888857e+01, '2026-07-20 01:02:04', '2026-11-21 03:29:05')
