VALUES (9652, 'tt0073580', NULL, 'The Passenger', 'Professione: reporter', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/A8jYH43plz70dNmHy82zAHGTqxN.jpg', 'https://image.tmdb.org/t/p/original/9H64mSSezN1T9CQKgbgV06BCZM4.jpg', 'David Locke is a world-weary American journalist who has been sent to cover a conflict in northern Africa, but he makes little progress with the story. When he discovers the body of a stranger who looks similar to him, Locke assumes the dead man''s identity. However, he soon finds out that the man was an arms dealer, leading Locke into dangerous situations. Aided by a beautiful woman, Locke attempts to avoid both the police and criminals out to get him.', NULL, NULL, 1.8826, 7.249, 0, 2.025, '2026-08-08 02:23:49', '2026-11-21 03:29:05')
