VALUES (16771, 'tt0109219', NULL, 'Barcelona', 'Barcelona', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/7dgX3naR9EsFMvQhwHY8My6r5FR.jpg', 'https://image.tmdb.org/t/p/original/gyP4rLbexXLpXIBigzxGPJfZ3G9.jpg', 'During the 1980s, uptight Ted Boynton is a salesman working in the Barcelona office of a Chicago-based company. He receives an unexpected visit from his cousin Fred, a naval officer who has come to Spain on a public relations mission for a U.S. fleet. Not exactly friends in the past, Ted and Fred strike up relationships with women in the Spanish city and experience conflicts -- Ted with his employer, and Fred with the Barcelona community.', NULL, NULL, 1.1878, 6.3, 0, 8.18, '2026-08-12 02:31:31', '2026-11-21 03:29:05')
